  "a_sentences": [
    {
      "a_text": "Selon l'art. 221 al. 1 let. d et e CPC, la demande doit contenir les allégations de fait et l'indication des moyens de preuve pour chaque allégation.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "L'art. 400 al. 1 CO impose au mandataire de rendre compte de sa gestion sur demande.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Il est exceptionnellement admissible de satisfaire à l'obligation de motivation par renvoi à une pièce, notamment pour des décomptes ou des relevés de compte, à condition que le renvoi désigne spécifiquement un document et qu'il indique clairement quelles parties de celui-ci constituent les allégations de la partie.",
      "b_propositions": ["P3", "P4"]
    },
    {
      "a_text": "Le mandataire doit indiquer les prestations fournies de manière suffisamment détaillée pour qu'elles soient vérifiables.",
      "b_propositions": ["P5", "P6"]
    },
    {
      "a_text": "Le Tribunal fédéral a retenu qu'une vérification approximative des honoraires par l'autorité précédente ne diminue pas la force probante des preuves.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral a confirmé que l'intimée avait suffisamment allégué et prouvé sa créance.",
      "b_propositions": ["P8"]
    }
  ]
}
